'use strict';
const $ = s => document.querySelector(s);
const esc = v => String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num = n => String(n).padStart(2,'0');
const KEY='amc-educatech-v2';
const stageNames=['Preparar','Investigar','Diagnosticar','Corrigir','Validar','Comunicar'];
const missionProtocolChoices=['Seguir o manual, preservar dados e realizar intervenções internas apenas com o professor, PC desligado e fora da tomada.','Abrir a fonte para descobrir de onde vem a falha.','Trocar várias peças ao mesmo tempo para economizar testes.'];
const missionCommunicationChoices=['Informar sintoma, teste e causa sustentada, ação indicada e validação; sinalizar supervisão e limites do cenário.','Dizer apenas “resolvido”, pois os detalhes são desnecessários.','Afirmar que este diagnóstico serve para qualquer computador com o mesmo sintoma.'];
const missionValidationChoices=c=>[c.confirm,'Encerrar porque uma peça foi trocada, sem repetir a tarefa.','Considerar resolvido porque nenhuma reclamação nova chegou.'];
const safety='Na prática: desligue e retire da tomada antes de intervenções internas, com supervisão do professor e cuidados contra descarga eletrostática. Não abra fonte ou monitor. Preserve dados antes de reparos. Siga o manual do modelo.';
const statuses={demonstrated:'Demonstrado na simulação',submitted_for_review:'Para revisão docente',needs_review:'Precisa de revisão'};
const fresh=()=>({version:2,diagnostic:null,records:{},boss:{draft:{},attempts:[],status:'needs_review',selfReviewed:false,peerDiscussed:false},role:0});
let state=fresh(),view='home',filter=0,statusFilter='',categoryFilter='',active=null,feedback=null,support='',returnFocus=null,timer;
function validInt(v,min,max){return Number.isInteger(v)&&v>=min&&v<=max;}
const isObject=v=>v!==null&&typeof v==='object'&&!Array.isArray(v);
const expectedChoice=(c,stage)=>[1,2,3].includes(stage)?(c.id-1)%c.steps.length:0;
const maxChoice=(c,stage)=>[1,2,3].includes(stage)?c.steps.length-1:2;
function trimLog(log){while(log.length>500){const index=log.findIndex(entry=>!entry.ok);if(index<0)return log.slice(-500);log.splice(index,1);}return log;}
function validBossChoice(key,value){if(typeof value!=='string'||!/^\d{1,2}$/.test(value))return false;const job=bossJobs.find(j=>j.code===key.at(-1));const count=job&&/^(cause|fix)/.test(key)?cases[job.id-1].steps.length:3;return validInt(Number(value),0,count-1);}
function cleanDraft(raw){return Object.fromEntries(bossKeys.filter(k=>raw?.[k]===''||validBossChoice(k,raw?.[k])).map(k=>[k,raw[k]]));}
function completeDraft(raw){return isObject(raw)&&bossKeys.every(k=>validBossChoice(k,raw[k]));}
function evaluateBossDraft(d){return [d.priority==='0'&&d.safety==='0',bossJobs.every(j=>d['cause'+j.code]===String(j.step)),bossJobs.every(j=>d['fix'+j.code]===String(j.step)),bossJobs.every(j=>d['validate'+j.code]==='0'),d.handoff==='0'];}
function restore(raw){
  const s=fresh(); if(!isObject(raw)||raw.version!==2)return s;
  s.role=validInt(raw.role,0,1)?raw.role:0;
  if(isObject(raw.diagnostic)&&Array.isArray(raw.diagnostic.answers)&&raw.diagnostic.answers.length===3&&raw.diagnostic.answers.every(v=>validInt(v,0,2)))s.diagnostic={answers:[...raw.diagnostic.answers]};
  for(const c of cases){const r=isObject(raw.records)?raw.records[c.id]:null;if(!isObject(r))continue;
    const tested=Array.isArray(r.tested)?[...new Set(r.tested.filter(i=>validInt(i,0,c.steps.length-1)))]:[];
    const log=Array.isArray(r.log)?r.log.slice(-500).filter(x=>isObject(x)&&validInt(x.stage,0,5)&&validInt(x.choice,0,maxChoice(c,x.stage))).map(x=>({stage:x.stage,choice:x.choice,ok:x.ok===true&&x.choice===expectedChoice(c,x.stage)})):[];
    const claimed=validInt(r.stage,0,6)?r.stage:0;let stage=0,cursor=-1;
    while(stage<claimed){const index=log.findIndex((x,i)=>i>cursor&&x.stage===stage&&x.ok);if(index<0||stage===1&&!tested.includes(expectedChoice(c,1)))break;cursor=index;stage++;}
    s.records[c.id]={stage,tested,errors:validInt(r.errors,0,1000000)?r.errors:0,hints:validInt(r.hints,0,2)?r.hints:0,status:stage===6?'demonstrated':'needs_review',log,self:validInt(r.self,0,2)?r.self:0};
  }
  const b=raw.boss;
  if(isObject(b)){s.boss.draft=cleanDraft(b.draft);
    s.boss.attempts=Array.isArray(b.attempts)?b.attempts.slice(-100).filter(a=>isObject(a)&&completeDraft(a.draft)).map((a,index)=>{const draft=cleanDraft(a.draft);return {version:validInt(a.version,1,1000000)?a.version:index+1,criteria:evaluateBossDraft(draft),draft,review:{self:a.review?.self===true,peer:a.review?.peer===true}};}):[];
    s.boss.status=s.boss.attempts.length&&s.boss.attempts.at(-1).criteria.every(Boolean)?'submitted_for_review':'needs_review';
    s.boss.selfReviewed=b.selfReviewed===true;s.boss.peerDiscussed=b.peerDiscussed===true;
  }return s;
}
function parseBackup(raw){
  if(!isObject(raw)||raw.format!=='amc-educatech'||raw.version!==2||!validInt(raw.role,0,1)||!isObject(raw.records)||!isObject(raw.boss)||!isObject(raw.boss.draft)||!Array.isArray(raw.boss.attempts)||raw.boss.attempts.length>100)throw Error('format');
  if(raw.diagnostic!==null&&(!isObject(raw.diagnostic)||!Array.isArray(raw.diagnostic.answers)||raw.diagnostic.answers.length!==3||!raw.diagnostic.answers.every(v=>validInt(v,0,2))))throw Error('diagnostic');
  if(Object.keys(raw.records).some(key=>!cases.some(c=>String(c.id)===key)))throw Error('records');
  const recovered=restore(raw);
  for(const [id,r]of Object.entries(raw.records)){const c=cases[Number(id)-1];if(!isObject(r)||!validInt(r.stage,0,6)||!Array.isArray(r.tested)||!r.tested.every(v=>validInt(v,0,c.steps.length-1))||!validInt(r.errors,0,1000000)||!validInt(r.hints,0,2)||!validInt(r.self,0,2)||!Array.isArray(r.log)||r.log.length>500||r.log.some(x=>!isObject(x)||!validInt(x.stage,0,5)||!validInt(x.choice,0,maxChoice(c,x.stage))||typeof x.ok!=='boolean')||recovered.records[id].stage!==r.stage)throw Error('record');}
  if(Object.keys(raw.boss.draft).some(k=>!bossKeys.includes(k)||raw.boss.draft[k]!==''&&!validBossChoice(k,raw.boss.draft[k]))||raw.boss.attempts.some(a=>!isObject(a)||!completeDraft(a.draft)||!Array.isArray(a.criteria)||a.criteria.length!==5||a.criteria.some(v=>typeof v!=='boolean')))throw Error('boss');
  return recovered;
}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('#save-status').textContent='Progresso salvo neste navegador';}catch{$('#save-status').textContent='Sem salvamento · baixe seu registro';announce('Não foi possível salvar neste navegador. Use Meu percurso → Baixar registro.');}}
function announce(msg){$('#announcement').textContent=msg;$('#announcement').hidden=false;clearTimeout(timer);timer=setTimeout(()=>$('#announcement').hidden=true,5000);}
function record(c){return state.records[c.id]||=( {stage:0,tested:[],errors:0,hints:0,status:'needs_review',log:[],self:0});}
const done=()=>cases.filter(c=>state.records[c.id]?.stage===6);
const xp=()=>Object.values(state.records).reduce((a,r)=>a+r.stage*10,0);
const target=c=>(c.id-1)%c.steps.length;
const sorted=(items,seed)=>items.map((text,i)=>({text,i,sort:((i+1)*2654435761^(seed*1597334677))>>>0})).sort((a,b)=>a.sort-b.sort);
const btn=(text,attrs='',cls='primary')=>`<button class="${cls}" ${/\btype=/.test(attrs)?'':'type="button"'} ${attrs}>${text}</button>`;
function stats(){return `<section class="stats" aria-label="Seu progresso"><div class="stat"><strong>${done().length}<small> / 50</small></strong><span>chamados resolvidos na simulação</span></div><div class="stat"><strong>${xp()} <small>XP</small></strong><span>percurso · sem conversão em nota</span></div><div class="stat"><strong>${levels.filter(l=>done().some(c=>c.level===l.id)).length}<small> / 5</small></strong><span>estações com prática concluída</span></div><div class="stat"><strong>${Object.values(state.records).filter(r=>r.stage===6&&r.errors>0).length}</strong><span>chamados revistos após feedback</span></div></section>`;}
function heading(k,title,desc=''){return `<div class="section-head"><div><p class="eyebrow">${k}</p><h1>${title}</h1></div>${desc?`<p>${desc}</p>`:''}</div>`;}
function trail(){return `<div class="trail">${levels.map(l=>{const n=done().filter(c=>c.level===l.id).length;return `<button class="station" data-station="${l.id}"><span class="station-no">${num(l.id)}</span><h3>${l.name}</h3><p>${l.desc}</p><small>${n} de 10 chamados · ${l.id<=2?'prática com modelo':l.id<=4?'análise e comparação':'autonomia com supervisão'}</small><span class="bar" aria-hidden="true"><i style="width:${n*10}%"></i></span></button>`;}).join('')}</div>`;}
function home(){const pending=cases.find(c=>state.records[c.id]&&state.records[c.id].stage<6);const next=pending||cases.find(c=>!state.records[c.id])||cases[0];return `<section class="hero"><div><p class="eyebrow hero-label">CENTRAL DE APRENDIZAGEM · AMC</p><h1>O próximo diagnóstico<br>começa com <em>você.</em></h1><p class="lead">O laboratório da escola precisa voltar a funcionar. Assuma a bancada, investigue 50 chamados e construa soluções com evidências.</p><div class="actions">${btn(state.diagnostic?(pending?'Retomar chamado':'Ir para a bancada')+' →':'Começar pelo diagnóstico →',state.diagnostic?`data-mission="${next.id}"`:'data-diagnostic="true"')}${btn('Explorar as 50 missões','data-view="missions"','secondary')}</div><div class="hero-meta"><span><b>5</b> estações</span><span><b>Sem</b> respostas digitadas</span><span><b>No seu</b> ritmo</span></div></div><aside class="dispatch"><div class="dispatch-top"><span>ORDEM DE SERVIÇO / ESCOLA</span><span class="dispatch-status"><i class="live-dot"></i>ABERTA</span></div><img class="bench-art" src="assets/brand/bancada.svg" alt="" width="720" height="370"><h2>Uma peça nova não é um diagnóstico.</h2><p><b>Coordenação do laboratório:</b> “Precisamos dos computadores de volta, com os dados preservados. Testem antes de trocar e deixem um registro que outra equipe consiga seguir.”</p><div class="dispatch-foot"><span>SEU PAPEL: EQUIPE TÉCNICA JÚNIOR</span><span>50 CHAMADOS</span></div></aside></section>${stats()}<div class="section-head"><div><p class="eyebrow">MAPA DA OPERAÇÃO</p><h2>Cinco estações. Mais autonomia a cada passo.</h2></div><p>Escolha um chamado em cada estação.<br>Os 50 casos ficam sempre disponíveis.</p></div>${trail()}<div class="two-col section-space"><section class="panel"><p class="eyebrow">COMO FUNCIONA</p><h2 class="section-space">Investigue. Decida. Revise.</h2><p>Selecione testes, leia os resultados e monte sua ordem de serviço. Cada decisão validada registra 10 XP uma única vez. Erros recebem orientação e novas tentativas livres.</p><div class="steps-mini"><span>01 · Evidências</span><span>02 · Correção</span><span>03 · Validação</span></div></section><section class="panel"><p class="eyebrow">SOZINHO OU EM DUPLA</p><h2 class="section-space">Duas pessoas. Uma decisão fundamentada.</h2><p>Primeiro, pense individualmente. Depois, compare a hipótese com seu par. Quem opera explica o teste; quem revisa procura a evidência. Troquem de papel a cada chamado.</p><div class="role">${roleText()}</div>${btn('Trocar papéis','data-role="true"','secondary')}</section></div><div class="safety"><b>Esta é uma simulação de raciocínio técnico.</b> Os resultados são didáticos e simplificados; não identificam defeitos de um computador real. ${safety}</div>`;}
function roleText(){return state.role===0?'Pessoa 1: opera e explica. Pessoa 2: confere a evidência e a segurança.':'Pessoa 2: opera e explica. Pessoa 1: confere a evidência e a segurança.';}
function missions(){const list=cases.filter(c=>(!filter||c.level===filter)&&(!categoryFilter||c.category===categoryFilter)&&(!statusFilter||(statusFilter==='new'?!state.records[c.id]:statusFilter==='done'?state.records[c.id]?.stage===6:state.records[c.id]&&state.records[c.id].stage<6)));return `${heading('PAINEL DE CHAMADOS','Qual problema vamos investigar?',`${list.length} chamados disponíveis · sem cronômetro`)}<p class="note">Comece por uma estação inicial ou escolha com o professor. Cada caso gera uma ordem de serviço; a última estação exige supervisão na prática.</p><div class="filterbar" aria-label="Filtros das missões">${[0,1,2,3,4,5].map(n=>btn(n?'Estação '+n:'Todas',`data-filter="${n}" aria-pressed="${filter===n}"`,'')).join('')}<label class="sr-only" for="mission-category">Categoria</label><select id="mission-category"><option value="">Todas as categorias</option>${[...new Set(cases.map(c=>c.category))].map(cat=>`<option ${cat===categoryFilter?'selected':''}>${esc(cat)}</option>`).join('')}</select><label class="sr-only" for="mission-status">Situação</label><select id="mission-status"><option value="">Todo o percurso</option><option value="new" ${statusFilter==='new'?'selected':''}>Ainda não iniciados</option><option value="progress" ${statusFilter==='progress'?'selected':''}>Em investigação</option><option value="done" ${statusFilter==='done'?'selected':''}>Resolvidos na simulação</option></select></div><div class="mission-grid">${list.map(c=>{const r=state.records[c.id];return `<article class="mission-card"><div class="card-top"><span>${esc(c.category)}</span><span>OS ${num(c.id)} / E${c.level}</span></div><h2>${esc(c.title)}</h2><p>${esc(c.symptom)}</p><div class="card-bottom"><span class="badge ${r&&r.stage<6?'review':''}">${r?(r.stage===6?'✓ Resolvido na simulação':'◷ Em investigação'):'Pronto para começar'}</span><small>${r?r.stage*10:0} / 60 XP</small></div>${btn(r?(r.stage===6?'Ver ordem de serviço':'Retomar investigação'):'Investigar chamado →',`data-mission="${c.id}"`)}</article>`;}).join('')}</div>${!list.length?'<div class="empty"><p>Nenhum chamado neste filtro.</p><button class="secondary" data-clear-filters>Ver todos os chamados</button></div>':''}`;}
const diagnosticQuestions=[
 {title:'Ventoinhas giram, mas não há imagem. O que isso comprova?',options:['Que a placa-mãe está funcionando perfeitamente.','Que há alguma alimentação, mas o POST ainda precisa ser verificado.','Que o monitor deve ser substituído.'],answer:1,tip:'Ventoinhas girando não garantem que o autoteste foi concluído. Separe alimentação, POST e vídeo.'},
 {title:'Antes de alterar o armazenamento para tentar reparar o sistema, você deve…',options:['formatar para eliminar as hipóteses.','instalar outro sistema imediatamente.','preservar os dados e verificar o backup e a chave de recuperação quando necessária.'],answer:2,tip:'Preservar os dados vem antes de procedimentos que possam alterá-los.'},
 {title:'Qual sequência produz um diagnóstico mais confiável?',options:['Observar → testar uma variável → corrigir a causa confirmada → validar.','Trocar várias peças → verificar se ligou.','Escolher a causa mais cara → reinstalar.'],answer:0,tip:'Uma variável por vez permite relacionar o efeito ao teste. Valide repetindo o contexto do defeito.'}
];
let diagnosticAnswers=[];
let importSequence=0;
function openDiagnostic(){returnFocus=document.activeElement;active={type:'diagnostic'};diagnosticAnswers=[];feedback=null;renderDiagnostic();$('#mission-dialog').showModal();}
function renderDiagnostic(){const i=diagnosticAnswers.length;$('#mission-content').innerHTML=`<div class="dialog-head"><span class="eyebrow">ENTRADA · SEM NOTA</span><button class="icon-btn" data-close="mission-dialog" aria-label="Fechar diagnóstico">×</button></div><h2 id="mission-title" class="mission-title">Um ponto de partida para sua investigação.</h2>${i<3?`<p class="context">Decisão ${i+1} de 3. Pense individualmente; depois compare com seu par.</p><h3 class="question-title">${diagnosticQuestions[i].title}</h3><div class="choice-grid">${diagnosticQuestions[i].options.map((o,n)=>`<button class="choice" data-diagnostic-choice="${n}"><span class="letter">${'ABC'[n]}</span>${o}</button>`).join('')}</div>`:`<div class="result"><b>Seu mapa inicial está pronto.</b><p>${diagnosticAnswers.filter((a,n)=>a===diagnosticQuestions[n].answer).length} de 3 decisões alinhadas ao método. Isso orienta o apoio; não bloqueia nenhum chamado.</p></div>${diagnosticQuestions.map((q,n)=>`<div class="result ${diagnosticAnswers[n]!==q.answer?'review':''}"><b>${n+1}. ${diagnosticAnswers[n]===q.answer?'Você já reconhece este princípio.':'Retome este princípio.'}</b><p>${q.tip}</p><p><b>Próximo passo:</b> ${n===0?'investigue o caso 03 para separar vídeo e POST.':n===1?'consulte os cuidados do caso 46.':'pratique o método no caso 01.'}</p></div>`).join('')}<div class="actions">${btn('Investigar o primeiro chamado →','data-start-first')}${btn('Escolher outro chamado','data-from-modal="missions"','secondary')}</div>`}`;}
function openMission(id){const c=cases.find(c=>c.id===id);if(!c)return;returnFocus=document.activeElement;active={type:'mission',id};feedback=null;support='';record(c);save();renderMission();if(!$('#mission-dialog').open)$('#mission-dialog').showModal();}
function choices(items,attr,seed){return `<div class="choice-grid">${sorted(items,seed).map((o,n)=>`<button class="choice" ${attr}="${o.i}"><span class="letter">${String.fromCharCode(65+n)}</span><span>${esc(o.text)}</span></button>`).join('')}</div>`;}
function resultHTML(){if(!feedback)return '';return `<div class="result ${feedback.ok?'':'review'}" role="status"><p><b>Potência:</b> ${esc(feedback.power)}</p><p><b>Ajuste:</b> ${esc(feedback.adjust)}</p><p><b>Próximo passo:</b> ${esc(feedback.next)}</p></div>`;}
function renderMission(){const c=cases.find(c=>c.id===active.id),r=record(c),t=target(c),s=c.steps[t];let body='';
  if(r.stage===0)body=`<h3 class="question-title">Prepare um atendimento seguro.</h3><p class="context">Leia o chamado e escolha o protocolo que orientará seus testes. Aqui você seleciona procedimentos; não execute intervenções reais sem o professor.</p>${choices(missionProtocolChoices,'data-answer',c.id)}`;
  if(r.stage===1)body=`<h3 class="question-title">Qual teste ajuda a isolar a falha?</h3><p class="context">Selecione uma verificação para consultar o resultado simulado. Comece pelo simples. As hipóteses são do roteiro original; nesta simulação uma delas foi escolhida como causa do chamado.</p><div class="choice-grid">${c.steps.map((step,i)=>`<button class="choice" data-test="${i}" aria-pressed="${r.tested.includes(i)}"><span class="letter">${num(i+1)}</span><span>${esc(step[1])}${r.tested.includes(i)?`<br><b>${i===t?'Evidência compatível com a causa':'Hipótese não sustentada neste cenário'}</b>`:''}</span></button>`).join('')}</div>${r.tested.length?`<div class="result"><b>Diário dos testes simulados</b>${r.tested.map(i=>`<p>Teste ${num(i+1)}: ${i===t?'o resultado sustenta a hipótese':'não foi encontrada evidência para'} “${esc(c.steps[i][0])}”.</p>`).join('')}</div>`:''}<div class="actions">${btn('Usar evidência e diagnosticar →',`data-next-test ${!r.tested.includes(t)?'disabled':''}`)}</div>`;
  if(r.stage===2)body=`<h3 class="question-title">Que hipótese a evidência sustenta?</h3><p class="context">Resultado do teste ${num(t+1)}: a verificação “${esc(s[1])}” sustentou uma causa neste cenário. Relacione o resultado ao diagnóstico.</p>${choices(c.steps.map(s=>s[0]),'data-answer',c.id+7)}`;
  if(r.stage===3)body=`<h3 class="question-title">Escolha a intervenção para a causa confirmada.</h3><p class="context"><b>Evidência:</b> ${esc(s[0])}. Outras intervenções podem fazer sentido em outro cenário. Neste chamado, escolha a que responde ao teste.</p>${choices(c.steps.map(s=>s[2]),'data-answer',c.id+13)}`;
  if(r.stage===4)body=`<h3 class="question-title">Como você confirma o resultado?</h3><p class="context">Uma correção precisa ser verificada antes da liberação. Selecione o critério de aceitação desta ordem de serviço.</p>${choices(missionValidationChoices(c),'data-answer',c.id+19)}`;
  if(r.stage===5)body=`<h3 class="question-title">Entregue um registro útil para a próxima equipe.</h3><p class="context">Sua ordem de serviço já reúne os dados abaixo. Escolha como comunicá-la à coordenação.</p>${serviceHTML(c)}${choices(missionCommunicationChoices,'data-answer',c.id+23)}`;
  if(r.stage===6)body=`<div class="result"><b>Chamado resolvido na simulação · 60 XP de percurso</b><p>Você vinculou um teste à hipótese, escolheu uma intervenção e definiu como validar. A execução real do procedimento será observada pelo professor.</p></div>${serviceHTML(c)}<label class="field" for="self-assessment">Como está sua autonomia neste chamado?<select id="self-assessment"><option value="0" ${r.self===0?'selected':''}>Ainda preciso de apoio para explicar</option><option value="1" ${r.self===1?'selected':''}>Consigo explicar com o roteiro</option><option value="2" ${r.self===2?'selected':''}>Consigo explicar a relação entre teste e causa</option></select></label><p class="note">Autoavaliação não altera a evidência registrada. Em dupla, a outra pessoa aponta no registro o teste que sustenta a solução.</p><div class="actions">${btn('Ir ao próximo chamado →',`data-mission="${c.id<50?c.id+1:1}"`)}${btn('Baixar esta ordem de serviço','data-export-case','secondary')}${btn('Ver meu percurso','data-from-modal="portfolio"','secondary')}</div>`;
  const supportHTML=support?`<div class="result"><b>${support==='hint'?'Carta de pista · supervisora de bancada':support==='model'?'Modelo do método':support==='mentor'?'Mentoria em dupla':'Cuidados do chamado'}</b><p>${support==='hint'?esc(hint(c,r)):support==='model'?'Sintoma → uma verificação → resultado observado → hipótese sustentada → intervenção coerente → repetição do teste. No mundo real, resultados podem ser inconclusivos e exigir encaminhamento.':support==='mentor'?esc(roleText())+' Quem revisa deve apontar a evidência antes de concordar. Se estiver sozinho, compare duas hipóteses no diário dos testes.':esc(c.note||safety)}</p></div>`:'';
  $('#mission-content').innerHTML=`<div class="dialog-head"><span class="eyebrow">OS ${num(c.id)} · ESTAÇÃO ${c.level} · ${esc(c.category)}</span><button class="icon-btn" data-close="mission-dialog" aria-label="Fechar chamado e salvar">×</button></div><h2 id="mission-title" class="mission-title" tabindex="-1">${esc(c.title)}</h2><p class="mission-symptom"><b>Relato do laboratório:</b> ${esc(c.symptom)}</p><ol class="stepper" aria-label="Etapas do atendimento">${stageNames.map((n,i)=>`<li class="${r.stage>=i?'active':''}" ${r.stage===i?'aria-current="step"':''}>${i<r.stage?'✓ ':''}${n}</li>`).join('')}</ol>${resultHTML()}${body}${r.stage<6?`<div class="modal-tools">${btn('Carta de pista ('+(2-r.hints)+'/2)',`data-support="hint" ${r.hints>=2?'disabled':''}`,'')}${btn('Consultar modelo','data-support="model"','')}${btn('Pedir mentoria','data-support="mentor"','')}${btn('Cuidados deste chamado','data-support="safety"','')}</div><p class="note">Pistas renovadas a cada chamado. Modelo, mentoria e revisão são sempre gratuitos. Nenhum erro retira acesso.</p>`:''}${supportHTML}`;
}
function hint(c,r){return ['Identifique quais opções protegem pessoas, componentes e dados antes da intervenção.','Compare as verificações na ordem do roteiro. Uma hipótese só deve ser descartada depois de consultar o resultado do seu teste.','Compare as palavras da hipótese com o teste que produziu evidência compatível no diário.','A intervenção deve responder à causa sustentada, sem corrigir um problema diferente.','Volte ao sintoma: que resultado observável mostraria que ele deixou de ocorrer?','Uma equipe que assume o chamado precisa saber o que foi testado e quais são os limites.'][r.stage]||'Explique ao seu par o elo entre teste, causa e solução.';}
function serviceHTML(c){const s=c.steps[target(c)];return `<section class="panel"><h3>Ordem de serviço · ${num(c.id)}</h3><p><b>Sintoma:</b> ${esc(c.symptom)}</p><p><b>Verificação simulada:</b> ${esc(s[1])}</p><p><b>Hipótese sustentada no cenário:</b> ${esc(s[0])}</p><p><b>Intervenção indicada:</b> ${esc(s[2])}</p><p><b>Critério de validação:</b> ${esc(c.confirm)}</p><p><b>Cuidados:</b> ${esc(c.note||safety)}</p></section>`;}
function answerMission(choice){const c=cases.find(c=>c.id===active.id),r=record(c);if(r.stage===1||r.stage>=6)return;const expected=(r.stage===2||r.stage===3)?target(c):0;const stage=r.stage,ok=choice===expected;r.log.push({stage,choice,ok});r.log=trimLog(r.log);
  if(ok){r.stage++;r.status=r.stage===6?'demonstrated':'needs_review';feedback={ok:true,power:['Você definiu um protocolo seguro.','','Você relacionou a causa à evidência.','A intervenção responde à causa sustentada.','Você definiu um resultado observável.','Seu registro comunica o caminho do diagnóstico.'][stage],adjust:stage===5?'Este registro demonstra raciocínio no cenário digital. A prática ainda precisa de observação docente.':'Mantenha o vínculo entre o teste e sua decisão nas próximas etapas.',next:stage===5?'Compare a ordem de serviço com seu par e registre sua autonomia.':'Continue para '+stageNames[r.stage].toLowerCase()+'.'};}
  else{r.errors++;feedback={ok:false,power:stage===0?'Você começou pela preparação do atendimento.':'Você já tem o chamado e os resultados anteriores para comparar.',adjust:stage===0?'Este protocolo não atende aos cuidados de segurança.':stage===2?'A hipótese escolhida não corresponde ao teste que sustentou uma causa.':stage===3?'A ação escolhida responde a outra hipótese deste roteiro.':stage===4?'A opção não verifica o retorno da função que falhava.':'Esse comunicado omite evidências ou generaliza além do cenário.',next:hint(c,r)+' Revise as opções e tente novamente.'};}support='';save();renderMission();$('#mission-title').focus();}
const bossJobs=[{id:46,step:0,code:'A',evidence:'Arquivos falham ao abrir e o HDD produz cliques repetidos de falha. Há dados insubstituíveis sem cópia confirmada.'},{id:1,step:1,code:'B',evidence:'A tomada foi verificada; o cabo de força está desconectado da tomada.'},{id:3,step:0,code:'C',evidence:'O monitor está na entrada DisplayPort, mas o cabo usado está conectado à entrada HDMI.'}];
const bossDecisions={priority:['A · Risco aos dados: parar usos não essenciais e avaliar preservação.','B · PC sem energia: insistir em ligar antes de avaliar os dados do A.','C · Ajustar o monitor antes de tratar o risco aos dados do A.'],safety:['Seguir manuais; desligar da tomada para intervenções internas; supervisão; preservar os dados antes de reparos.','Testar tudo energizado para observar os componentes.','Abrir a fonte para medir a rede elétrica.'],handoff:['Entregar os três registros com observações, hipóteses, ações e critérios de validação; sinalizar os limites e o encaminhamento do A.','Informar apenas “computadores prontos”, sem testar ou indicar pendências.','Garantir recuperação de todos os dados antes da avaliação especializada.']};
const bossKeys=['priority','safety','handoff',...bossJobs.flatMap(j=>['cause'+j.code,'fix'+j.code,'validate'+j.code])];
const rubricRows=[['Priorizar e proteger','Prioriza o risco aos dados do chamado A e escolhe o protocolo seguro.'],['Interpretar evidências','Relaciona cada uma das três observações à hipótese correspondente.'],['Indicar intervenções','Escolhe ações coerentes com as causas, incluindo encaminhamento quando necessário.'],['Validar ou encaminhar','Define como verificar cada retorno e preserva dados no caso A.'],['Comunicar o atendimento','Entrega registro com evidências, ações, validação e limites; o professor confere a explicação ou demonstração.']];
function rubric(){return `<table class="rubric"><caption class="sr-only">Critérios do desafio integrador, disponíveis antes da entrega</caption><thead><tr><th scope="col">Critério</th><th scope="col">Evidência essencial esperada</th></tr></thead><tbody>${rubricRows.map(r=>`<tr><th scope="row">${r[0]}</th><td>${r[1]}</td></tr>`).join('')}</tbody></table>`;}
function selectField(label,key,options,seed){const val=state.boss.draft[key];return `<label class="field">${esc(label)}<select data-boss-field="${key}" required><option value="">Selecione uma decisão</option>${sorted(options,seed).map(o=>`<option value="${o.i}" ${val===String(o.i)?'selected':''}>${esc(o.text)}</option>`).join('')}</select></label>`;}
function boss(){const b=state.boss,last=b.attempts.at(-1);return `${heading('BOSS FIGHT FORMATIVA','Operação: laboratório de volta.', 'Três chamados. Um plano integrado. Revisão livre.')}<div class="panel"><h2>A coordenação precisa de uma decisão técnica.</h2><p>Escolha a prioridade e monte um plano para os três computadores. As observações já foram coletadas neste cenário. Combine proteção, evidências e encaminhamento em uma ordem de serviço para outra equipe.</p><p>Prática recomendada: concluir ao menos um chamado de cada estação (${levels.filter(l=>done().some(c=>c.level===l.id)).length}/5). Você pode explorar este desafio a qualquer momento.</p><details><summary>Ver a rubrica antes de decidir</summary>${rubric()}</details><p><b>Como será registrado:</b> decisões incompletas ou incoerentes ficam em revisão. Um plano coerente fica disponível para revisão docente; a plataforma não atesta execução real nem atribui nota.</p></div>${last?`<div class="result ${b.status==='needs_review'?'review':''}" role="status"><b>${statuses[b.status]} · versão ${last.version||b.attempts.length}</b><p><b>Potência:</b> ${last.criteria.some(Boolean)?'Há critérios sustentados pelo seu plano.':'Você apresentou uma primeira versão que pode ser revisada.'}</p><p><b>Ajuste:</b> ${last.criteria.every(Boolean)?'A defesa e a execução ainda precisam ser observadas pelo professor.':'Retome os critérios sinalizados abaixo e compare com as evidências.'}</p><p><b>Próximo passo:</b> ${last.criteria.every(Boolean)?'Baixe o registro e explique ou demonstre seu plano ao professor.':'Use os roteiros de apoio, altere suas decisões e entregue uma nova versão.'}</p>${last.criteria.map((v,i)=>`<p>${v?'✓ Coerente no plano':'↻ Revisar'} · ${rubricRows[i][0]}: ${!v?rubricRows[i][1]:i===4?'a mensagem inclui os campos essenciais; a comunicação será observada pelo professor.':'decisões correspondem ao cenário.'}</p>`).join('')}</div>`:''}<p id="boss-draft-note" class="note" ${last&&bossKeys.some(k=>b.draft[k]!==last.draft[k])?'':'hidden'}>Há alterações no rascunho. Elas ainda não foram registradas como uma nova versão.</p><form id="boss-form"><div class="two-col section-space"><section class="panel"><h2>Checkpoint 1 · Prioridade</h2>${selectField('Qual atendimento requer primeiro uma medida de proteção?','priority',bossDecisions.priority,73)}${selectField('Qual protocolo orienta a equipe?','safety',bossDecisions.safety,71)}</section><section class="panel"><h2>As evidências da equipe</h2>${bossJobs.map(j=>`<p class="section-space"><b>Computador ${j.code} · caso ${num(j.id)}</b><br>${esc(j.evidence)}</p>`).join('')}<p class="section-space">As observações são específicas desta simulação; sintomas semelhantes podem ter outras causas.</p></section></div><div class="section-head"><div><p class="eyebrow">CHECKPOINT 2</p><h2>Monte as três partes do plano.</h2></div></div><div class="mission-grid">${bossJobs.map(j=>{const c=cases[j.id-1];return `<section class="panel"><h2>Computador ${j.code}</h2><p>${esc(j.evidence)}</p>${selectField('Hipótese sustentada','cause'+j.code,c.steps.map(s=>s[0]),j.id)}${selectField('Ação ou encaminhamento','fix'+j.code,c.steps.map(s=>s[2]),j.id+9)}${selectField('Como acompanhar o resultado','validate'+j.code,[c.confirm,'Encerrar sem verificar dados nem função.','Concluir porque um componente parece novo.'],j.id+19)}${btn('Consultar roteiro '+num(c.id),`data-reference="${c.id}"`,'secondary')}</section>`;}).join('')}</div><section class="panel section-space"><h2>Checkpoint 3 · Comunicação e revisão</h2>${selectField('Como encaminhar a ordem de serviço à coordenação?','handoff',bossDecisions.handoff,91)}<div class="checks"><label><input type="checkbox" id="boss-self" ${b.selfReviewed?'checked':''} required> Comparei minhas decisões com a rubrica e as evidências dos três computadores.</label><label><input type="checkbox" id="boss-peer" ${b.peerDiscussed?'checked':''}> Discuti o plano com meu par (opcional; não altera os critérios).</label></div><p>Na conversa, explique por que a prioridade A muda a sequência. Quem preferir pode apontar os campos da ordem de serviço e demonstrar o fluxo com as cartas, com os mesmos critérios.</p><div class="actions">${btn(b.attempts.length?'Entregar versão revisada →':'Verificar e registrar plano →','type="submit"')}${btn('Baixar registro do percurso','type="button" data-export="md"','secondary')}</div></section></form>`;}
function evaluateBoss(){return evaluateBossDraft(state.boss.draft);}
function portfolio(){const started=cases.filter(c=>state.records[c.id]);return `${heading('COMPARAÇÃO CONSIGO MESMO','Seu percurso deixa evidências.','Cada registro pertence a este navegador e endereço.')}${stats()}<div class="two-col"><section class="panel"><h2>Conquistas com critérios</h2><p>${done().length?'✓ Primeiro diagnóstico · pelo menos uma ordem de serviço concluída na simulação.':'○ Primeiro diagnóstico · conclua uma ordem de serviço na simulação.'}</p><p class="section-space">${done().some(c=>state.records[c.id].errors>0)?'✓':'○'} Revisão em ação · conclua um chamado após corrigir uma decisão com feedback.</p><p class="section-space">${levels.every(l=>done().some(c=>c.level===l.id))?'✓':'○'} Percurso diverso · conclua um chamado em cada uma das cinco estações.</p><p class="section-space">XP descreve decisões validadas no percurso. Essas conquistas não são certificado de competência prática.</p></section><section class="panel"><h2>Guardar e continuar</h2><p>Baixe o portfólio com as decisões, tentativas e ordens de serviço. O JSON permite restaurar o percurso desta versão em outro navegador. Nenhum arquivo é enviado automaticamente.</p><div class="actions">${btn('Baixar portfólio .md','data-export="md"')}${btn('Baixar registro .json','data-export="json"','secondary')}${btn('Restaurar registro','data-import','secondary')}</div><input type="file" id="import-file" accept=".json,application/json" hidden><div class="actions">${btn('Imprimir percurso','data-print','secondary')}${btn('Recomeçar percurso','data-reset','subtle')}</div></section></div><section class="panel section-space"><h2>Diagnóstico inicial</h2><p>${state.diagnostic?state.diagnostic.answers.filter((a,i)=>a===diagnosticQuestions[i].answer).length+' de 3 decisões alinhadas ao método na entrada. A comparação com os registros abaixo orienta a conversa com o professor.':'Seu ponto de partida ainda não foi registrado.'}</p>${btn(state.diagnostic?'Refazer diagnóstico inicial':'Fazer diagnóstico inicial','data-diagnostic','secondary')}</section><section class="panel section-space"><h2>Ordens de serviço</h2>${started.length?started.map(c=>{const r=state.records[c.id];return `<article class="portfolio-row"><div><h3>OS ${num(c.id)} · ${esc(c.title)}</h3><p>${statuses[r.status]} · ${r.stage}/6 etapas · ${r.errors} decisões revistas · ${r.hints} pistas consultadas</p><p>${r.stage===6?['Autoavaliação: ainda preciso de apoio.','Autoavaliação: explico com roteiro.','Autoavaliação: explico a relação entre teste e causa.'][r.self]:'Próxima etapa: '+stageNames[r.stage]}</p></div>${btn('Abrir registro',`data-mission="${c.id}"`,'secondary')}</article>`;}).join(''):'<p>Nenhum chamado iniciado. Escolha um caso para criar sua primeira evidência.</p>'}</section><section class="panel section-space"><h2>Desafio integrador</h2><p>${state.boss.attempts.length?statuses[state.boss.status]+' · '+(state.boss.attempts.at(-1).version||state.boss.attempts.length)+' versões registradas (até 100 mantidas no histórico).' :'Ainda sem entrega.'} A observação de execução, a explicação e a avaliação final ficam com o professor.</p>${btn('Abrir desafio','data-view="boss"','secondary')}</section>`;}
function teacher(){return `${heading('PLANO DOCENTE · EDUCATECH','Da leitura do roteiro à decisão técnica.','Proposta inicial · ajuste após observar a turma.')}<div class="teacher-grid"><section class="panel"><h2>1 · Diagnóstico e objetivo</h2><p><b>Hipótese pedagógica a verificar:</b> estudantes consultam soluções sem relacionar testes, evidências e decisões. Público assumido: iniciantes de AMC, em duplas, celulares compartilháveis, aula de 50 minutos.</p><p class="section-space"><b>Objetivo:</b> analisar um chamado, escolher verificação, sustentar hipótese, indicar ação segura e definir validação, comunicando os limites do diagnóstico.</p><p class="section-space">Esta é uma experiência de gamificação educacional com cenários didáticos. Aprendizagem baseada em jogos usa um jogo como recurso; um jogo sério constitui uma simulação com finalidade formativa; jogo educativo é uma categoria ampla. O uso de XP, sozinho, não define aprendizagem.</p></section><section class="panel"><h2>2 · Roteiro de 50 minutos</h2><ol class="text-list"><li><b>0–5 min:</b> apresente o chamado da coordenação e os cuidados.</li><li><b>5–10 min:</b> diagnóstico individual; discussão e devolutiva em pares.</li><li><b>10–25 min:</b> cada dupla resolve 1–2 chamados; alterne operador e revisor.</li><li><b>25–40 min:</b> desafio integrador, rubrica, primeira versão e feedback.</li><li><b>40–47 min:</b> revisão do plano e explicação ou demonstração com cartas.</li><li><b>47–50 min:</b> autoavaliação e exportação. Retome outras estações nas próximas aulas.</li></ol></section><section class="panel full"><h2>3 · Alinhamento e evidências</h2><table class="rubric"><thead><tr><th>Objetivo / critério</th><th>Atividade / produção / registro</th><th>Feedback / recuperação / fonte</th></tr></thead><tbody><tr><td>Selecionar teste e sustentar hipótese com evidência.</td><td>Testes simulados → ordem de serviço por seleção → diário de testes e decisões. Aplicação: explicar ou apontar no plano o elo entre teste e causa.</td><td>Comparar hipótese e teste; consultar modelo; repetir decisão. Fontes: 50 casos originais e manuais indicados no roteiro.</td></tr><tr><td>Indicar intervenção segura para a causa.</td><td>Protocolo de atendimento + ação indicada; plano integrado de três computadores. Aplicação: simular o fluxo com cartas ou demonstrar na bancada supervisionada.</td><td>Um acerto observado, ajuste e próximo passo; revisão sem perda de acesso. Fontes: cuidados e soluções dos casos originais.</td></tr><tr><td>Validar resultado e comunicar limites.</td><td>Critério de aceitação + entrega do plano; explicação/demonstração ao professor, com a mesma rubrica.</td><td>Reabrir a ordem, comparar versões e refazer trecho. Fontes: confirmação de reparo dos casos e semana 5.</td></tr></tbody></table></section><section class="panel"><h2>4 · Narrativa, papéis e escolhas</h2><p>Equipe técnica júnior atende o laboratório escolar. A coordenação solicita o serviço; a supervisora oferece pistas orientadoras. A ordem de serviço e o diário de testes funcionam como artefatos profissionais.</p><p class="section-space">O aluno escolhe chamados, ordem dos testes e apoio. Papéis rotativos: operar/explicar e conferir evidências/segurança. Missão opcional: compare dois casos da mesma categoria e aponte, nos roteiros, por que sintomas parecidos admitem causas diferentes.</p></section><section class="panel"><h2>5 · Economia simples e inclusiva</h2><p>10 XP por etapa validada, no máximo 60 por chamado. Retomar ou abrir uma ordem concluída não concede XP extra. Não há ranking, punição por tempo nem compra de nota.</p><p class="section-space">Duas consultas de pista por chamado; modelo, cuidados, mentoria e revisão permanecem livres. A quantidade limita apenas a carta complementar, sem bloquear o conteúdo essencial. Sem moeda adicional para reduzir a carga de gestão.</p><p class="section-space">Crafting: teste + evidência + ação + validação = ordem de serviço. Primeira versão + feedback + revisão = plano integrado aprimorado.</p></section><section class="panel full"><h2>6 · Boss fight e avaliação formativa</h2><p>Três chamados combinam risco aos dados, alimentação e vídeo. A rubrica é conhecida antes da entrega. A plataforma verifica coerência das escolhas; a avaliação final continua docente.</p>${rubric()}<p><b>Níveis docentes:</b> em desenvolvimento = lacuna em critério essencial; adequado = decisões coerentes e explicadas com evidência; avançado = transfere o método a outro caso e reconhece limites com autonomia. Não use apenas XP para decidir esses níveis.</p><p class="section-space"><b>Registros:</b> “demonstrated” indica apenas as decisões demonstradas no cenário digital; “needs_review” indica revisão necessária ou percurso incompleto; “submitted_for_review” indica plano coerente preparado para revisão docente. Comunicação real, colaboração e execução de bancada exigem observação.</p></section><section class="panel"><h2>7 · Inclusão e retomada</h2><p>Respostas por botões, seletores e caixas de marcação; sem escrita livre obrigatória. Navegação por teclado, instruções textuais, contraste e ritmo livre. A alternativa à fala é apontar e demonstrar o fluxo no plano ou com cartas, preservando evidência e critérios.</p><p class="section-space">Sem dispositivo: imprima os roteiros na biblioteca, cubra a coluna de solução e use cartões A/B/C ou fichas de teste, hipótese, ação e validação. O professor lê os resultados e anota decisões. Feedback e critérios permanecem iguais.</p><p class="section-space">Recuperação: retome o modelo do método, compare uma hipótese com seu teste, revise a escolha e tente um novo caso da mesma categoria.</p></section><section class="panel"><h2>8 · Fontes e limites</h2><p>Foram aplicadas as cinco transcrições em educatech-materiais: intenção pedagógica; mecânicas; narrativa; economia; avaliação formativa. Os 50 casos originais são a fonte disciplinar. Os resultados simulados são simplificados, com uma hipótese designada por chamado.</p><p class="section-space">O conteúdo não substitui o manual do equipamento. A oficina não solicita nomes nem contas e não usa IA para atribuir notas. Progresso e preferências ficam no navegador e nas exportações locais. O painel de acessibilidade oferece síntese de voz e VLibras; a ativação do VLibras conecta o navegador ao serviço externo, e vozes online também podem usar rede.</p><ul class="text-list">${references.map(r=>`<li><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)}</a></li>`).join('')}</ul></section></div><div class="actions">${btn('Imprimir plano docente','data-print')}${btn('Abrir biblioteca para preparar cartas','data-library','secondary')}</div>`;}
function render(focus=true){
  const focused=document.activeElement;let keepFocus=null;
  if(!focus&&focused&&$('#main').contains(focused)){
    if(focused.id)keepFocus='#'+focused.id;
    else for(const key of ['filter','role','clear-filters'])if(focused.hasAttribute('data-'+key)){keepFocus='[data-'+key+'="'+focused.getAttribute('data-'+key)+'"]';break;}
  }
  $('#main').innerHTML=({home,missions,boss,portfolio,teacher}[view]||home)();
  document.querySelectorAll('.navigation [data-view]').forEach(b=>{if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});
  if(focus){$('#main').focus();window.scrollTo(0,0);}else if(keepFocus){$('#main').querySelector(keepFocus)?.focus({preventScroll:true});}
}
function navigate(next){view=next;render();}
function download(text,name,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function decisionText(c,entry){
  const choices=entry.stage===0?missionProtocolChoices:entry.stage===1?c.steps.map(s=>s[1]):entry.stage===2?c.steps.map(s=>s[0]):entry.stage===3?c.steps.map(s=>s[2]):entry.stage===4?missionValidationChoices(c):missionCommunicationChoices;
  return choices[entry.choice]||'Registro incompleto';
}
function caseMarkdown(c){const r=state.records[c.id],s=c.steps[target(c)];return `## OS ${num(c.id)} — ${c.title}\n\nSituação: ${statuses[r.status]}. Etapas: ${r.stage}/6. Decisões revistas: ${r.errors}. Pistas: ${r.hints}.\n\nSintoma: ${c.symptom}\n\n${r.stage===6?`- Verificação simulada: ${s[1]}\n- Causa sustentada no cenário: ${s[0]}\n- Intervenção indicada: ${s[2]}\n- Validação: ${c.confirm}\n- Cuidados: ${c.note||safety}\n- Autoavaliação: ${['preciso de apoio','explico com roteiro','explico a relação teste/causa'][r.self]}\n`:'Registro em construção. Nenhuma conclusão atestada.\n'}\nTestes consultados: ${r.tested.map(i=>num(i+1)+': '+c.steps[i][1]).join(' | ')||'nenhum'}.\n\nDecisões registradas:\n${r.log.map(l=>`- ${stageNames[l.stage]}: ${decisionText(c,l)} · ${l.ok?'coerente':'revisar'}`).join('\n')}\n`;}
function bossSummary(attempt){
  const labels={priority:'Prioridade',safety:'Protocolo de segurança',handoff:'Comunicação'};
  return Object.keys(labels).map(k=>`- ${labels[k]}: ${validBossChoice(k,attempt.draft[k])?bossDecisions[k][Number(attempt.draft[k])]:'Não selecionado'}`).join('\n')+`\n- Autoavaliação com rubrica: ${attempt.review?.self?'declarada':'não registrada'}.\n- Discussão com par (autodeclaração): ${attempt.review?.peer?'declarada':'não registrada'}.`;
}
function portfolioMarkdown(){return `# AMC · Operação Bancada — Portfólio\n\nRegistro local sem identificação pessoal. ${xp()} XP de percurso; ${done().length}/50 chamados concluídos na simulação. XP não é nota.\n\n${safety}\n\n## Ponto de partida\n\n${state.diagnostic?state.diagnostic.answers.map((a,i)=>`${i+1}. ${diagnosticQuestions[i].title}\nEscolha inicial: ${diagnosticQuestions[i].options[a]}\n${a===diagnosticQuestions[i].answer?'Alinhada ao método.':'Retomar: '+diagnosticQuestions[i].tip}`).join('\n\n'):'Não registrado.'}\n\n${cases.filter(c=>state.records[c.id]).map(caseMarkdown).join('\n---\n\n')}\n## Desafio integrador\n\n${state.boss.attempts.length?statuses[state.boss.status]:'Sem entrega'}. Execução real e comunicação dependem de observação docente.\n\n${state.boss.attempts.map((a,i)=>`### Versão ${a.version||i+1}\n\n${bossSummary(a)}\n\n${a.criteria.map((v,n)=>`- ${rubricRows[n][0]}: ${v?'coerente no plano':'revisar'}`).join('\n')}\n\n${bossJobs.map(j=>{const c=cases[j.id-1],d=a.draft;return `Computador ${j.code}: ${j.evidence}\nHipótese: ${c.steps[Number(d['cause'+j.code])]?.[0]||'não selecionada'}\nAção: ${c.steps[Number(d['fix'+j.code])]?.[2]||'não selecionada'}\nValidação: ${d['validate'+j.code]==='0'?c.confirm:'Critério inadequado; revisar.'}\n`;}).join('\n')}`).join('\n\n')}\n\n## Limites\n\nResultados simulados, uma hipótese designada por chamado. Não substituem diagnóstico real ou manual. Registros de escolhas não certificam execução, colaboração ou competência profissional.\n`;}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b||b.disabled)return;
  if(b.hasAttribute('data-view'))navigate(b.dataset.view);
  if(b.hasAttribute('data-close'))$('#'+b.dataset.close).close();
  if(b.hasAttribute('data-mission'))openMission(Number(b.dataset.mission));
  if(b.hasAttribute('data-station')){filter=Number(b.dataset.station);statusFilter='';categoryFilter='';navigate('missions');}
  if(b.hasAttribute('data-filter')){filter=Number(b.dataset.filter);render(false);}
  if(b.hasAttribute('data-clear-filters')){filter=0;statusFilter='';categoryFilter='';render(false);}
  if(b.hasAttribute('data-role')){state.role=1-state.role;save();render(false);announce('Papéis trocados. '+roleText());}
  if(b.hasAttribute('data-diagnostic'))openDiagnostic();
  if(b.hasAttribute('data-diagnostic-choice')){diagnosticAnswers.push(Number(b.dataset.diagnosticChoice));if(diagnosticAnswers.length===3){state.diagnostic={answers:[...diagnosticAnswers]};save();}renderDiagnostic();$('#mission-dialog').scrollTop=0;$('#mission-title').setAttribute('tabindex','-1');$('#mission-title').focus();}
  if(b.hasAttribute('data-start-first')){openMission(1);}
  if(b.hasAttribute('data-from-modal')){$('#mission-dialog').close();navigate(b.dataset.fromModal);}
  if(b.hasAttribute('data-answer')&&active?.type==='mission')answerMission(Number(b.dataset.answer));
  if(b.hasAttribute('data-test')&&active?.type==='mission'){const c=cases[active.id-1],r=record(c),i=Number(b.dataset.test);if(r.stage!==1)return;if(!r.tested.includes(i))r.tested.push(i);feedback=null;save();renderMission();$(`[data-test="${i}"]`).focus();announce('Teste '+num(i+1)+': '+(i===target(c)?'evidência compatível com a causa.':'hipótese não sustentada neste cenário.'));}
  if(b.hasAttribute('data-next-test')&&active?.type==='mission'){const c=cases[active.id-1],r=record(c);if(r.stage===1&&r.tested.includes(target(c))){r.log.push({stage:1,choice:target(c),ok:true});r.stage=2;feedback={ok:true,power:'Você obteve uma evidência para sustentar a hipótese.',adjust:'Este resultado pertence ao cenário simulado.',next:'Relacione o resultado à hipótese correspondente.'};save();renderMission();$('#mission-title').focus();}}
  if(b.hasAttribute('data-support')&&active?.type==='mission'){support=b.dataset.support;const r=record(cases[active.id-1]);if(support==='hint'){if(r.hints>=2)return;r.hints++;save();}renderMission();$('#mission-dialog').scrollTop=$('#mission-dialog').scrollHeight;}
  if(b.hasAttribute('data-export-case')&&active?.type==='mission')download(caseMarkdown(cases[active.id-1]),'amc-os-'+num(active.id)+'.md','text/markdown;charset=utf-8');
  if(b.hasAttribute('data-export')){if(b.dataset.export==='json')download(JSON.stringify({...state,format:'amc-educatech'},null,2),'amc-percurso.json','application/json');else download(portfolioMarkdown(),'amc-portfolio.md','text/markdown;charset=utf-8');announce('Registro baixado. Guarde o arquivo no seu dispositivo.');}
  if(b.hasAttribute('data-import'))$('#import-file').click();
  if(b.hasAttribute('data-print'))window.print();
  if(b.hasAttribute('data-reset'))$('#reset-dialog').showModal();
  if(b.id==='confirm-reset'){state=fresh();save();$('#reset-dialog').close();active=null;navigate('home');announce('Percurso reiniciado.');}
  if(b.hasAttribute('data-reference')){const c=cases[Number(b.dataset.reference)-1];returnFocus=b;active={type:'reference',id:c.id};$('#mission-content').innerHTML=`<div class="dialog-head"><span class="eyebrow">APOIO · ROTEIRO ORIGINAL</span><button class="icon-btn" data-close="mission-dialog" aria-label="Fechar roteiro">×</button></div><h2 id="mission-title">${esc(c.title)}</h2><p class="context">${esc(c.symptom)}</p>${c.steps.map((s,i)=>`<section class="panel section-space"><h3>${i+1}. ${esc(s[0])}</h3><p><b>Verificar:</b> ${esc(s[1])}</p><p><b>Ação:</b> ${esc(s[2])}</p></section>`).join('')}<div class="safety">${esc(c.note||safety)}</div>`;$('#mission-dialog').showModal();}
  if(b.hasAttribute('data-library'))location.href='biblioteca.html';
});
document.addEventListener('change',async event=>{const e=event.target;
  if(e.id==='mission-category'){categoryFilter=e.value;render(false);}
  if(e.id==='mission-status'){statusFilter=e.value;render(false);}
  if(e.id==='self-assessment'&&active?.type==='mission'){record(cases[active.id-1]).self=Number(e.value);save();}
  if(e.hasAttribute('data-boss-field')){const b=state.boss;if(b.draft[e.dataset.bossField]!==e.value){b.selfReviewed=false;$('#boss-self').checked=false;}b.draft[e.dataset.bossField]=e.value;const last=b.attempts.at(-1);$('#boss-draft-note').hidden=!last||!bossKeys.some(k=>b.draft[k]!==last.draft[k]);save();}
  if(e.id==='boss-self'||e.id==='boss-peer'){state.boss[e.id==='boss-self'?'selfReviewed':'peerDiscussed']=e.checked;save();}
  if(e.id==='import-file'){const file=e.files[0];if(!file)return;const request=++importSequence;try{if(file.size>2000000)throw Error('size');const data=JSON.parse(await file.text());if(request!==importSequence)return;const recovered=parseBackup(data);state=recovered;save();render(false);announce('Percurso restaurado do arquivo local.');}catch{if(request===importSequence)announce('Arquivo inválido ou incompleto. Seu percurso atual foi mantido. Escolha um registro AMC Educatech versão 2 de até 2 MB.');}e.value='';}
});
document.addEventListener('submit',event=>{if(event.target.id!=='boss-form')return;event.preventDefault();const criteria=evaluateBoss();state.boss.selfReviewed=$('#boss-self').checked;state.boss.peerDiscussed=$('#boss-peer').checked;state.boss.attempts.push({version:(state.boss.attempts.at(-1)?.version||state.boss.attempts.length)+1,criteria,draft:{...state.boss.draft},review:{self:state.boss.selfReviewed,peer:state.boss.peerDiscussed}});state.boss.attempts=state.boss.attempts.slice(-100);state.boss.status=criteria.every(Boolean)?'submitted_for_review':'needs_review';save();render();announce(criteria.every(Boolean)?'Plano registrado para revisão docente.':'Plano registrado. Revise os critérios sinalizados e tente novamente.');});
$('#mission-dialog').addEventListener('close',()=>{const origin=returnFocus;render(false);if(origin?.isConnected){origin.focus();return;}let replacement;for(const key of ['mission','reference','diagnostic','view'])if(origin?.hasAttribute('data-'+key)){replacement=$('#main').querySelector(`[data-${key}="${origin.getAttribute('data-'+key)}"]`);if(replacement)break;} (replacement||$('#main')).focus();});
try{state=restore(JSON.parse(localStorage.getItem(KEY)||'null'));}catch{$('#save-status').textContent='Use o portfólio para guardar seu percurso';}
render(false);
